import{_ as t,o as a,c as i,a5 as s}from"./chunks/framework.bIR-4glx.js";const k=JSON.parse('{"title":"Speaking Evidence Card: From Accent Anxiety to Verifiable Interaction","description":"Preserve unscripted speech, unfamiliar follow-ups, listener retellings, reference variety, comprehension effort, repair, and delayed transfer without treating accent similarity or recognition scores as speaking ability.","frontmatter":{"title":"Speaking Evidence Card: From Accent Anxiety to Verifiable Interaction","description":"Preserve unscripted speech, unfamiliar follow-ups, listener retellings, reference variety, comprehension effort, repair, and delayed transfer without treating accent similarity or recognition scores as speaking ability.","updated":"2026-09-02T00:00:00.000Z","worksheetDownload":{"url":"/downloads/worksheets/speaking-evidence.en.md","name":"speaking-evidence.en.md"}},"headers":[],"relativePath":"en/templates/speaking-evidence.md","filePath":"en/templates/speaking-evidence.md","lastUpdated":1788307200000}'),n={name:"en/templates/speaking-evidence.md"};function r(d,e,l,o,h,p){return a(),i("div",null,[...e[0]||(e[0]=[s(`<h1 id="speaking-evidence-card-from-accent-anxiety-to-verifiable-interaction" tabindex="-1">Speaking Evidence Card: From Accent Anxiety to Verifiable Interaction <a class="header-anchor" href="#speaking-evidence-card-from-accent-anxiety-to-verifiable-interaction" aria-label="Permalink to &quot;Speaking Evidence Card: From Accent Anxiety to Verifiable Interaction&quot;">​</a></h1><p>Copy this card into a private note for one real situation at a time. Keep raw recordings private by default. Before recording another person or using customer, family, medical, or unreleased project information, obtain necessary permission or practise with fictional details.</p><h2 id="_1-define-the-task-listener-and-boundary" tabindex="-1">1. Define the Task, Listener, and Boundary <a class="header-anchor" href="#_1-define-the-task-listener-and-boundary" aria-label="Permalink to &quot;1. Define the Task, Listener, and Boundary&quot;">​</a></h2><div class="language-markdown vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">markdown</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-light-font-weight:bold;--shiki-dark:#79B8FF;--shiki-dark-font-weight:bold;"># Speaking Evidence - YYYY-MM-DD</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">Real situation:</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">Task: explain / answer / repair / collaborate / transfer</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">Listener and relationship:</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">What the listener must know or do afterwards:</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">Time limit:</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">Allowed notes / retakes / captions / dictionary / AI:</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">Recording and upload permission:</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">Content that must remain private:</span></span></code></pre></div><p>Write completion as a listener result, such as &quot;can retell the risk and next step&quot;, not only &quot;sounds fluent&quot;.</p><h2 id="_2-record-reference-variety-and-technical-conditions" tabindex="-1">2. Record Reference Variety and Technical Conditions <a class="header-anchor" href="#_2-record-reference-variety-and-technical-conditions" aria-label="Permalink to &quot;2. Record Reference Variety and Technical Conditions&quot;">​</a></h2><div class="language-markdown vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">markdown</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">Current reference variety or audio source:</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">Why it fits:</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">Differences I only need to recognise, not force myself to imitate:</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">Other English varieties added this cycle:</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">Device / microphone:</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">Network / room noise:</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">Recording or call platform:</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">Listener familiarity with the topic and my accent:</span></span></code></pre></div><p>When device, network, or listener familiarity changes, do not assign the entire score difference to ability.</p><h2 id="_3-preserve-three-unscripted-baselines" tabindex="-1">3. Preserve Three Unscripted Baselines <a class="header-anchor" href="#_3-preserve-three-unscripted-baselines" aria-label="Permalink to &quot;3. Preserve Three Unscripted Baselines&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Sample</th><th>Condition</th><th>Recording</th><th>First break</th><th>Task completed?</th></tr></thead><tbody><tr><td>90-120 second monologue</td><td>Explain a real experience/problem without a script</td><td></td><td></td><td></td></tr><tr><td>Five-turn exchange</td><td>Include at least one unfamiliar follow-up</td><td></td><td></td><td></td></tr><tr><td>One interaction repair</td><td>Repetition, scope confirmation, rephrasing, or summary</td><td></td><td></td><td></td></tr></tbody></table><div class="language-markdown vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">markdown</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">One-sentence main point:</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">Two details the listener must hear:</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">Critical number / time / responsibility / condition:</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">What I most expect to be misunderstood:</span></span></code></pre></div><p>Do not remove pauses, clean noise, or ask AI for a script first. The baseline shows what remains when scaffolding leaves.</p><h2 id="_4-preserve-what-the-listener-actually-heard" tabindex="-1">4. Preserve What the Listener Actually Heard <a class="header-anchor" href="#_4-preserve-what-the-listener-actually-heard" aria-label="Permalink to &quot;4. Preserve What the Listener Actually Heard&quot;">​</a></h2><p>Ask the listener to hear the recording before seeing a transcript:</p><table tabindex="0"><thead><tr><th>Listener/condition</th><th>Retold gist</th><th>Retold details</th><th>Guess/replay point</th><th>Next response</th></tr></thead><tbody><tr><td>Listener A</td><td></td><td></td><td></td><td></td></tr><tr><td>Listener B or new device</td><td></td><td></td><td></td><td></td></tr></tbody></table><div class="language-markdown vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">markdown</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">Noticeable accent that remained intelligible:</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">Place where meaning was actually lost:</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">Place that required effort without misunderstanding:</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">Familiarity or bias that may shape the feedback:</span></span></code></pre></div><p>One subjective impression is not a conclusion. Preserve what the person heard and could do, not only whether you resembled a prestige accent.</p><h2 id="_5-build-a-high-impact-problem-map" tabindex="-1">5. Build a High-Impact Problem Map <a class="header-anchor" href="#_5-build-a-high-impact-problem-map" aria-label="Permalink to &quot;5. Build a High-Impact Problem Map&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Segment/time</th><th>Listener may hear</th><th>Intended meaning</th><th>Type</th><th>Task impact</th><th>This cycle&#39;s action</th></tr></thead><tbody><tr><td></td><td></td><td></td><td>sound / ending / stress / pause / chunk / grammar / organisation</td><td>meaning-changing / task-blocking / recurring / effortful / low-impact difference</td><td></td></tr></tbody></table><p>Choose only one to three problems. When a difference marks reference variety, region, or personal voice and does not raise comprehension cost, record it without forcing it away.</p><h2 id="_6-move-from-chunks-into-unfamiliar-follow-ups" tabindex="-1">6. Move from Chunks into Unfamiliar Follow-ups <a class="header-anchor" href="#_6-move-from-chunks-into-unfamiliar-follow-ups" aria-label="Permalink to &quot;6. Move from Chunks into Unfamiliar Follow-ups&quot;">​</a></h2><div class="language-markdown vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">markdown</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">Five replaceable chunks:</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">1.</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">2.</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">3.</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">4.</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">5.</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">Topic variation:</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">Position variation:</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">Listener variation:</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">Unfamiliar follow-up:</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">Unscripted answer:</span></span></code></pre></div><p>When fluency exists only inside a memorised script, reduce complete-sentence memorisation and increase keyword reconstruction plus follow-ups.</p><h2 id="_7-record-interaction-repair" tabindex="-1">7. Record Interaction Repair <a class="header-anchor" href="#_7-record-interaction-repair" aria-label="Permalink to &quot;7. Record Interaction Repair&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Break</th><th>How I noticed</th><th>Repair action</th><th>Listener response</th><th>How shared understanding was confirmed</th></tr></thead><tbody><tr><td>Not heard / scope unclear / thinking needed / expression failed / agreement unstable</td><td></td><td></td><td></td><td></td></tr></tbody></table><div class="language-markdown vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">markdown</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">My repetition or confirmation request:</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">My rephrasing:</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">My final summary of agreement:</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">If repair failed, the one change for next time:</span></span></code></pre></div><p>Repair is not a penalty. Failing to notice a misunderstanding, or failing to restore the task after noticing it, is the training signal.</p><h2 id="_8-record-teacher-listener-and-ai-feedback" tabindex="-1">8. Record Teacher, Listener, and AI Feedback <a class="header-anchor" href="#_8-record-teacher-listener-and-ai-feedback" aria-label="Permalink to &quot;8. Record Teacher, Listener, and AI Feedback&quot;">​</a></h2><div class="language-markdown vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">markdown</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">Reviewer / tool / model version and date:</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">Did it use raw audio or a transcript?</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">Speech-recognition transcript errors:</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">Problems it marked as high impact:</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">Did it separate accent difference, misunderstanding, effort, grammar, register, and style?</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">Dictionary audio, teacher, or real-listener check:</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">What I accepted / rejected, and why:</span></span></code></pre></div><p>Recognition scores change with microphone, noise, network, model, and accent. Treat them as clues only.</p><h2 id="_9-test-delayed-retention-and-transfer" tabindex="-1">9. Test Delayed Retention and Transfer <a class="header-anchor" href="#_9-test-delayed-retention-and-transfer" aria-label="Permalink to &quot;9. Test Delayed Retention and Transfer&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Time</th><th>What is removed</th><th>Changed condition</th><th>Output</th><th>Listener result</th></tr></thead><tbody><tr><td>Day 1</td><td>No AI-written script</td><td>Original situation</td><td>First take and retake</td><td></td></tr><tr><td>Days 3-7</td><td>Old script and model audio removed</td><td>New topic or listener</td><td>90-120 seconds plus follow-up</td><td></td></tr><tr><td>Day 14</td><td>Recent feedback removed</td><td>New device, accent, or time pressure</td><td>Collaboration/decision explanation</td><td></td></tr><tr><td>Day 30</td><td>All practice prompts closed</td><td>Real meeting, interview, or conversation</td><td>Complete task</td><td></td></tr></tbody></table><div class="language-markdown vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">markdown</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">What remained retrievable after seven days:</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">What failed again after conditions changed:</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">Did the listener guess or replay less often?</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">Next variable:</span></span></code></pre></div><h2 id="_10-score-and-decide" tabindex="-1">10. Score and Decide <a class="header-anchor" href="#_10-score-and-decide" aria-label="Permalink to &quot;10. Score and Decide&quot;">​</a></h2><p>Score 0-2: <code>0=not completed</code>, <code>1=prompt-dependent or unstable</code>, <code>2=completed under the current condition</code>.</p><table tabindex="0"><thead><tr><th>Item</th><th style="text-align:right;">Day 1</th><th style="text-align:right;">Day 7</th><th style="text-align:right;">Day 14</th><th>Evidence reason</th></tr></thead><tbody><tr><td>Complete task and main line</td><td style="text-align:right;"></td><td style="text-align:right;"></td><td style="text-align:right;"></td><td></td></tr><tr><td>Listener recovers critical information</td><td style="text-align:right;"></td><td style="text-align:right;"></td><td style="text-align:right;"></td><td></td></tr><tr><td>Understanding does not require repeated guessing/replay</td><td style="text-align:right;"></td><td style="text-align:right;"></td><td style="text-align:right;"></td><td></td></tr><tr><td>Handle an unfamiliar follow-up</td><td style="text-align:right;"></td><td style="text-align:right;"></td><td style="text-align:right;"></td><td></td></tr><tr><td>Notice and repair an interaction break</td><td style="text-align:right;"></td><td style="text-align:right;"></td><td style="text-align:right;"></td><td></td></tr><tr><td>Complete after listener, device, or topic changes</td><td style="text-align:right;"></td><td style="text-align:right;"></td><td style="text-align:right;"></td><td></td></tr></tbody></table><div class="language-markdown vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">markdown</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">Current evidence supports: continue same problem / add variation / move to another problem / pause</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">Most important evidence:</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">Conclusion I still cannot draw:</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">Smallest next task:</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">Next review date:</span></span></code></pre></div><p>Related chapters: <a href="./../threads/part-1/5-speaking">Speaking: Make Meaning Arrive</a> | <a href="./../threads/part-1/3-listening">Listening</a> | <a href="./../threads/part-1/8-job-search-english">Job-search English</a> | <a href="./evidence-chain">Evidence Chain Template</a></p>`,38)])])}const g=t(n,[["render",r]]);export{k as __pageData,g as default};
